def add(a: float, b: float) -> float:
    return a + b

def multiply(a: float, b: float) -> float:
    return a * b

class UserService:
    def __init__(self):
        self._users = {}

    def get_user(self, user_id: str):
        return self._users.get(user_id)

    def register_user(self, user_id: str, name: str):
        if not user_id or not name:
            raise ValueError('Invalid user parameters')
        self._users[user_id] = name
        return True

import logging

logger = logging.getLogger(__name__)

def log_event(event_name: str, level: int = logging.INFO):
    if not event_name:
        return
    logger.log(level, f'Event: {event_name}')

def format_currency(amount: float, currency_symbol: str = '$') -> str:
    if amount < 0:
        return f'-{currency_symbol}{abs(amount):,.2f}'
    return f'{currency_symbol}{amount:,.2f}'

import re

def is_valid_uuid(val: str) -> bool:
    uuid_regex = r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    return bool(re.match(uuid_regex, val, re.IGNORECASE))

def read_and_count_lines(filepath: str) -> int:
    # Resource leak: file is never closed
    f = open(filepath, 'r')
    lines = f.readlines()
    return len(lines)

def dynamic_math_eval(user_expr: str):
